const getSpendingSummary = `-- name: GetSpendingSummary :one

WITH visible AS (
    SELECT t.amount, a.type AS account_type, c.is_income, c.is_transfer, c.is_fixed
    FROM transactions t
    JOIN accounts a    ON a.id = t.account_id
    JOIN account_access v ON v.account_id = a.id
    LEFT JOIN categories c ON c.id = t.category_id
    WHERE v.household_id = $1
      AND (v.user_id = $2 OR v.is_shared)
      AND a.is_active
      AND NOT t.excluded_from_reports
      AND NOT ($5::bool AND t.is_one_time)
      AND NOT t.pending
      AND t.date >= $3 AND t.date <= $4
)
SELECT
    COALESCE(SUM(-amount) FILTER (WHERE is_income), 0)::numeric        AS income,
    COALESCE(SUM(ABS(amount))  FILTER (WHERE NOT COALESCE(is_income, FALSE)
                                    AND NOT COALESCE(is_transfer, FALSE)
                                    AND is_spend(amount, account_type)), 0)::numeric       AS spending,
    COALESCE(SUM(ABS(amount))  FILTER (WHERE COALESCE(is_fixed, FALSE)
                                    AND is_spend(amount, account_type)), 0)::numeric       AS fixed_spending,
    COALESCE(SUM(ABS(amount))  FILTER (WHERE NOT COALESCE(is_income, FALSE)
                                    AND NOT COALESCE(is_transfer, FALSE)
                                    AND NOT COALESCE(is_fixed, FALSE)
                                    AND is_spend(amount, account_type)), 0)::numeric       AS discretionary_spending,
    COUNT(*)::bigint                                                    AS transaction_count
FROM visible
`

type GetSpendingSummaryParams struct {
	HouseholdID    uuid.UUID    `json:"household_id"`
	UserID         uuid.UUID    `json:"user_id"`
	Date           stdtime.Time `json:"date"`
	Date_2         stdtime.Time `json:"date_2"`
	ExcludeOneTime bool         `json:"exclude_one_time"`
}

type GetSpendingSummaryRow struct {
	Income                decimal.Decimal `json:"income"`
	Spending              decimal.Decimal `json:"spending"`
	FixedSpending         decimal.Decimal `json:"fixed_spending"`
	DiscretionarySpending decimal.Decimal `json:"discretionary_spending"`
	TransactionCount      int64           `json:"transaction_count"`
}

// Reporting queries.
//
// Conventions that every query here shares, and that the numbers depend on:
//
//   - Plaid signs amounts as POSITIVE = money leaving the account, EXCEPT on a
//     `loan` account, where it inverts: a payment (money actually spent) is
//     negative. is_spend(amount, account_type) is the one place that exception
//     lives; every "is this row an outflow" test calls it instead of comparing
//     amount > 0 directly. Income has no loan-account equivalent to invert, so
//     it is still -sum(amount) over negative rows in income categories.
//   - Transfers are excluded from BOTH income and spending. Moving money
//     between your own accounts is neither, and counting it would inflate
//     both sides. This is also what stops credit-card payments being
//     double-counted against the purchases they settle.
//   - Every total is computed here, in NUMERIC, never in the application and
//     never in JavaScript.
//   - Visibility is always scoped: own items plus shared household items.
//   - excluded_from_reports rows are ALWAYS dropped. is_one_time rows are
//     dropped only when the caller passes exclude_one_time — see below.
//
// The two exclusion flags answer different questions, and conflating them is
// how a report starts lying:
//
//	excluded_from_reports  "this did not happen"      — always honoured
//	is_one_time            "this happened, but it is  — honoured on request
//	                        not evidence about a
//	                        typical month"
//
// So a $14k loan payoff belongs in July's Spending page (the money left) and
// must NOT sit in the six-month average that predicts August's fixed bills.
// Every query that reports on a REAL PERIOD passes exclude_one_time = false —
// which is also the zero value, so an existing caller keeps its meaning. Only
// a query feeding a TRAILING BASELINE passes true. If you add a caller, ask
// which of those two things it is; there is no third answer.
// Headline figures for one period: what came in, what went out, and what was
// left to invest.
func (q *Queries) GetSpendingSummary(ctx context.Context, arg GetSpendingSummaryParams) (GetSpendingSummaryRow, error) {
	row := q.db.QueryRow(ctx, getSpendingSummary,
		arg.HouseholdID,
		arg.UserID,
		arg.Date,
		arg.Date_2,
		arg.ExcludeOneTime,
	)
	var i GetSpendingSummaryRow
	err := row.Scan(
		&i.Income,
		&i.Spending,
		&i.FixedSpending,
		&i.DiscretionarySpending,
		&i.TransactionCount,
	)
	return i, err
}

const getTopMerchants = `-- name: GetTopMerchants :many
SELECT
    COALESCE(
        me.canonical_name,
        (array_agg(COALESCE(t.merchant_name, t.name) ORDER BY t.date DESC))[1]
    )::text                                                AS merchant,
    COALESCE(ma.entity_id::text, t.merchant_key, '')::text AS merchant_key,
    SUM(ABS(t.amount))::numeric            AS total,
    COUNT(*)::bigint                  AS transaction_count
FROM transactions t
JOIN accounts a    ON a.id = t.account_id
JOIN account_access v ON v.account_id = a.id
LEFT JOIN categories c ON c.id = t.category_id
LEFT JOIN merchant_aliases ma
       ON ma.household_id = $1
      AND ma.merchant_key = t.merchant_key
      AND ma.source <> 'suggested'
LEFT JOIN merchant_entities me ON me.id = ma.entity_id
WHERE v.household_id = $1
  AND (v.user_id = $2 OR v.is_shared)
  AND a.is_active
  AND NOT t.excluded_from_reports
  AND NOT t.pending
  AND t.date >= $3 AND t.date <= $4
  AND NOT COALESCE(c.is_income, FALSE)
  AND NOT COALESCE(c.is_transfer, FALSE)
  AND is_spend(t.amount, a.type)
GROUP BY me.canonical_name, 2
ORDER BY total DESC
LIMIT $5
`

type GetTopMerchantsParams struct {
	HouseholdID uuid.UUID    `json:"household_id"`
	UserID      uuid.UUID    `json:"user_id"`
	Date        stdtime.Time `json:"date"`
	Date_2      stdtime.Time `json:"date_2"`
	Limit       int32        `json:"limit"`
}

type GetTopMerchantsRow struct {
	Merchant         string          `json:"merchant"`
	MerchantKey      string          `json:"merchant_key"`
	Total            decimal.Decimal `json:"total"`
	TransactionCount int64           `json:"transaction_count"`
}

// Grouped by canonical merchant: fragments of one business that the household
// has merged (see merchants.sql) collapse into a single row under the entity's
// name. With no aliases the COALESCE falls straight through to the descriptor
// and the result reads as it did before canonicalisation existed.
//
// merchant_key is the RESOLVED key, which is what makes a row here a link: it
// addresses the merchant detail view for both a merged entity and a bare
// descriptor, and it is stable across a later merge because resolution is
// idempotent.
//
// The grouping is BY THAT KEY, not by the display name. Grouping by name splits
// one merchant across several rows whenever the bank varies its own text —
// "THE HOME DEPOT #4905" and "THE HOME DEPOT 4905" normalise to one key and are
// one business, but as names they are two, and they listed as two top merchants
// with two different totals that both linked to the same detail page. A row and
// the page it opens have to agree.
//
// The name shown is the most RECENT descriptor for the key, matching how
// ListMerchantKeyStats picks its sample: the form a merchant bills under now is
// the form the user recognises.
func (q *Queries) GetTopMerchants(ctx context.Context, arg GetTopMerchantsParams) ([]GetTopMerchantsRow, error) {
	rows, err := q.db.Query(ctx, getTopMerchants,
		arg.HouseholdID,
		arg.UserID,
		arg.Date,
		arg.Date_2,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetTopMerchantsRow{}
	for rows.Next() {
		var i GetTopMerchantsRow
		if err := rows.Scan(
			&i.Merchant,
			&i.MerchantKey,
			&i.Total,
			&i.TransactionCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

